import{_ as i,W as u,s as o,u as d,I as s,ah as l,w as a,Z as p,A as n}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const k=JSON.parse('{"title":"一行命令轻松升级 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"一行命令轻松升级 Ubuntu | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"一行命令轻松升级 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一行命令轻松升级 Ubuntu | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171128 Easily Upgrade Ubuntu to a Newer Version with This Single Command","title":"一行命令轻松升级 Ubuntu","tag":"201712"},"relativePath":"201712/20171128 Easily Upgrade Ubuntu to a Newer Version with This Single Command.md","filePath":"[post].md"}'),r={name:"201712/20171128 Easily Upgrade Ubuntu to a Newer Version with This Single Command.md"};function b(g,t,h,c,m,v){const e=u("Link");return d(),o("div",null,[t[15]||(t[15]=s("h1",{id:"一行命令轻松升级-ubuntu",tabindex:"-1"},[a("一行命令轻松升级 Ubuntu "),s("a",{class:"header-anchor",href:"#一行命令轻松升级-ubuntu","aria-label":"Permalink to 一行命令轻松升级 Ubuntu"},"​")],-1)),t[16]||(t[16]=s("p",null,[s("img",{src:"https://itsfoss.com/wp-content/uploads/2017/11/upgrade-ubuntu-single-command-featured-800x450.jpg",alt:"Upgrade Ubuntu to a newer version with a single command"})],-1)),s("p",null,[p(e,{href:"https://github.com/TurboLabIt/zzupdate"},{default:n(()=>t[0]||(t[0]=[a("zzupdate")])),_:1}),t[1]||(t[1]=a(" 是一个开源的命令行程序，通过将几个更新命令组合到一个命令中，使得将 Ubuntu 桌面和服务器版本升级到更新版本的任务变得容易一些。"))]),t[17]||(t[17]=l(`<p>将 Ubuntu 系统升级到更新的版本并不是一项艰巨的任务。无论是使用 GUI 还是使用几个命令，都可以轻松地将系统升级到最新版本。</p><p>另一方面，Gianluigi &#39;Zane&#39; Zanettini 写的 <code>zzupdate</code> 只需一个命令就可以在 Ubuntu 中清理、更新、自动删除、版本升级、该工具自我更新。</p><p>它会清理本地缓存，更新可用的软件包信息，然后执行发行版升级。接着，它会更新该工具并删除未使用的软件包。</p><p>该脚本必须以 root 用户身份运行。</p><h3 id="安装-zzupdate-将-ubuntu-升级到更新的版本" tabindex="-1">安装 zzupdate 将 Ubuntu 升级到更新的版本 <a class="header-anchor" href="#安装-zzupdate-将-ubuntu-升级到更新的版本" aria-label="Permalink to 安装 zzupdate 将 Ubuntu 升级到更新的版本">​</a></h3><p>要安装 <code>zzupdate</code>，请在终端中执行以下命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -s https://raw.githubusercontent.com/TurboLabIt/zzupdate/master/setup.sh | sudo sh</span></span></code></pre></div><p>然后将提供的示例配置文件复制到 <code>zzupdate.conf</code> 并设置你的首选项。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp /usr/local/turbolab.it/zzupdate/zzupdate.default.conf /etc/turbolab.it/zzupdate.conf</span></span></code></pre></div><p>完成后，只要使用下面的命令，它就会开始升级你的 Ubuntu 系统到一个更新的版本（如果有的话）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo zzupdate</span></span></code></pre></div><p>请注意，在普通版本（非 LTS 版本）下，zzupdate 会将系统升级到下一个可用的版本。但是，当你运行 Ubuntu 16.04 LTS 时，它将尝试仅搜索下一个长期支持版本，而不是可用的最新版本。</p><p>如果你想退出 LTS 版本并升级到最新版本，你将需要更改一些选项。</p><p>对于 Ubuntu 桌面，打开 <strong>软件和更新</strong> 和下面 <strong>更新</strong> 选项卡，并更改通知我新的 Ubuntu 版本选项为 “<strong>对于任何新版本</strong>”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/11/software-update-any-new-version-800x378.jpeg" alt="Software Updater in Ubuntu"></p><p>对于 Ubuntu 服务版，编辑 <code>release-upgrades</code> 文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vi /etc/update-manager/release-upgrades</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Prompt=normal</span></span></code></pre></div><h3 id="配置-zzupdate-可选" tabindex="-1">配置 zzupdate [可选] <a class="header-anchor" href="#配置-zzupdate-可选" aria-label="Permalink to 配置 zzupdate [可选]">​</a></h3><p><code>zzupdate</code> 要配置的选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REBOOT=1</span></span></code></pre></div><p>如果值为 1，升级后系统将重启。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REBOOT_TIMEOUT=15</span></span></code></pre></div><p>将重启超时设置为 900 秒，因为某些硬件比其他硬件重启需要更长的时间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VERSION_UPGRADE=1</span></span></code></pre></div><p>如果升级可用，则执行版本升级。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VERSION_UPGRADE_SILENT=0</span></span></code></pre></div><p>自动显示版本进度。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>COMPOSER_UPGRADE=1</span></span></code></pre></div><p>值为 “1” 会自动升级该工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SWITCH_PROMPT_TO_NORMAL=0</span></span></code></pre></div><p>此功能将 Ubuntu 版本更新为普通版本，即如果你运行着 LTS 发行版，<code>zzupdate</code> 将不会将其升级到 Ubuntu 17.10（如果其设置为 0）。它将仅搜索 LTS 版本。相比之下，无论你运行着 LTS 或者普通版，“1” 都将搜索最新版本。</p><p>完成后，你要做的就是在控制台中运行一个完整的 Ubuntu 系统更新。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo zzupdate</span></span></code></pre></div><h3 id="最后的话" tabindex="-1">最后的话 <a class="header-anchor" href="#最后的话" aria-label="Permalink to 最后的话">​</a></h3><p>尽管 Ubuntu 的升级过程本身就很简单，但是 zzupdate 将它简化为一个命令。不需要编码知识，这个过程完全是配置文件驱动。我个人发现这是一个很好的更新几个 Ubuntu 系统的工具，而无需单独关心不同的事情。</p><p>你愿意试试吗？</p><hr>`,37)),s("p",null,[t[3]||(t[3]=a("via: ")),p(e,{href:"https://itsfoss.com/zzupdate-upgrade-ubuntu/"},{default:n(()=>t[2]||(t[2]=[a("https://itsfoss.com/zzupdate-upgrade-ubuntu/")])),_:1})]),s("p",null,[t[7]||(t[7]=a("作者：")),p(e,{href:"https://itsfoss.com"},{default:n(()=>t[4]||(t[4]=[a("Ambarish Kumar")])),_:1}),t[8]||(t[8]=a(" 译者：")),p(e,{href:"https://github.com/geekpi"},{default:n(()=>t[5]||(t[5]=[a("geekpi")])),_:1}),t[9]||(t[9]=a(" 校对：")),p(e,{href:"https://github.com/wxy"},{default:n(()=>t[6]||(t[6]=[a("wxy")])),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ")),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>t[10]||(t[10]=[a("LCTT")])),_:1}),t[13]||(t[13]=a(" 原创编译，")),p(e,{href:"https://linux.cn/"},{default:n(()=>t[11]||(t[11]=[a("Linux中国")])),_:1}),t[14]||(t[14]=a(" 荣誉推出"))])])}const T=i(r,[["render",b]]);export{k as __pageData,T as default};
